INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-mae-rim-1-0',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ แม่ริม (ล้านนา)',
        'The Golden Relic Stupa of Mae Rim (ล้านนา)',
        'sacred',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.8717,
        98.905,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เชียงใหม่ (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ล้านนา เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Chiang Mai (Thailand), serving as the spiritual heart of ancestral ล้านนา heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เชียงใหม่ (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Chiang Mai (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน แม่ริม',
        'Remove footwear and maintain silence within the inner terrace of Mae Rim.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-mae-rim-1-0',
        'วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ แม่ริม (ล้านนา)',
        'The White Lady Specter of Mae Rim (ล้านนา)',
        'ghost',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.8717,
        98.905,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น เชียงใหม่ (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ แม่ริม',
        'A chilling paranormal account from Chiang Mai (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Mae Rim.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ล้านนา ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ล้านนา oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ แม่ริม',
        'Never whistle or look back if hearing whispers along twilight pathways in Mae Rim.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-mae-rim-1-0',
        'อสุรกายพญาเงาแห่งพงไพร แม่ริม (ล้านนา)',
        'The Shadow Beast of Mae Rim (ล้านนา)',
        'monster',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.8717,
        98.905,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เชียงใหม่ (ไทย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ แม่ริม',
        'Eyewitness reports of a formidable cryptid stalking Chiang Mai (Thailand). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Mae Rim.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ล้านนา ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ล้านนา folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ แม่ริม',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Mae Rim.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-mae-rim-1-0',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม แม่ริม (ล้านนา)',
        'The Inscribed Hex and Tragic Fate of Mae Rim (ล้านนา)',
        'curse',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.8717,
        98.905,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เชียงใหม่ (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน แม่ริม',
        'A grim cautionary curse chronicle from Chiang Mai (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Mae Rim.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ล้านนา เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ล้านนา, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ แม่ริม',
        'Never remove stones, relics, or votive offerings from Mae Rim.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-mae-rim-1-0',
        'มหาปราการหินเมกะลิธและแนวสุริยะ แม่ริม (ล้านนา)',
        'The Megalithic Solar Alignments of Mae Rim (ล้านนา)',
        'legend',
        'เชียงใหม่ (ไทย)',
        'Chiang Mai (Thailand)',
        'แม่ริม',
        'Mae Rim',
        18.8717,
        98.905,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เชียงใหม่ (ไทย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ล้านนา ใน แม่ริม',
        'A legendary monumental marvel in Chiang Mai (Thailand). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ล้านนา engineers in Mae Rim.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เชียงใหม่ (ไทย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Chiang Mai (Thailand), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ แม่ริม',
        'Do not deface, carve, or displace ancient stones in Mae Rim.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ แม่ริม (ล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

