        'sacred',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5467,
        102.9719,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน บุรีรัมย์ (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อีสานใต้ขอมโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Buri Ram (Thailand), serving as the spiritual heart of ancestral อีสานใต้ขอมโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค บุรีรัมย์ (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Buri Ram (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เฉลิมพระเกียรติ',
        'Remove footwear and maintain silence within the inner terrace of Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-chaloem-phra-kiat-1-4',
        'วิญญาณทหารไร้นามแห่งสมรภูมิเก่า เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Nameless Sentinel Ghost of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'ghost',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5467,
        102.9719,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น บุรีรัมย์ (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ เฉลิมพระเกียรติ',
        'A chilling paranormal account from Buri Ram (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Chaloem Phra Kiat.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อีสานใต้ขอมโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of อีสานใต้ขอมโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เฉลิมพระเกียรติ',
        'Never whistle or look back if hearing whispers along twilight pathways in Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"วิญญาณทหารไร้นามแห่งสมรภูมิเก่า เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
