      ) VALUES (
        'pin-curse-chaloem-phra-kiat-1-4',
        'กระจกเงาต้องคำสาปและเงาลวงตา เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Cursed Scrying Glass of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'curse',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5467,
        102.9719,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง บุรีรัมย์ (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เฉลิมพระเกียรติ',
        'A grim cautionary curse chronicle from Buri Ram (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Chaloem Phra Kiat.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อีสานใต้ขอมโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อีสานใต้ขอมโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เฉลิมพระเกียรติ',
        'Never remove stones, relics, or votive offerings from Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"กระจกเงาต้องคำสาปและเงาลวงตา เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

