INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-sathing-phra-1-6',
        'คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด สทิงพระ (คาบสมุทรสทิงพระ)',
        'The Desecrated Tomb Hex of Sathing Phra (คาบสมุทรสทิงพระ)',
        'curse',
        'สงขลา (ไทย)',
        'Songkhla (Thailand)',
        'สทิงพระ',
        'Sathing Phra',
        7.5172,
        100.4539,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง สงขลา (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน สทิงพระ',
        'A grim cautionary curse chronicle from Songkhla (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Sathing Phra.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว คาบสมุทรสทิงพระ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of คาบสมุทรสทิงพระ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ สทิงพระ',
        'Never remove stones, relics, or votive offerings from Sathing Phra.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด สทิงพระ (คาบสมุทรสทิงพระ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-sathing-phra-1-6',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน สทิงพระ (คาบสมุทรสทิงพระ)',
        'The Bottomless Sacred Cenote of Sathing Phra (คาบสมุทรสทิงพระ)',
        'legend',
        'สงขลา (ไทย)',
        'Songkhla (Thailand)',
        'สทิงพระ',
        'Sathing Phra',
        7.5172,
        100.4539,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง สงขลา (ไทย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว คาบสมุทรสทิงพระ ใน สทิงพระ',
        'A legendary monumental marvel in Songkhla (Thailand). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คาบสมุทรสทิงพระ engineers in Sathing Phra.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ สงขลา (ไทย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Songkhla (Thailand), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ สทิงพระ',
        'Do not deface, carve, or displace ancient stones in Sathing Phra.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน สทิงพระ (คาบสมุทรสทิงพระ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-arashiyama-1-7',
        'เทวาลัยโบราณแห่งมหาเทวะ อาราชิยามะ (เฮอันโบราณ)',
        'The Ancient Chola Shiva Shrine of Arashiyama (เฮอันโบราณ)',
        'sacred',
        'เกียวโต (ญี่ปุ่น)',
        'Kyoto (Japan)',
        'อาราชิยามะ',
        'Arashiyama',
        34.9666,
        135.6322,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เกียวโต (ญี่ปุ่น) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เฮอันโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Kyoto (Japan), serving as the spiritual heart of ancestral เฮอันโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เกียวโต (ญี่ปุ่น) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Kyoto (Japan), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน อาราชิยามะ',
        'Remove footwear and maintain silence within the inner terrace of Arashiyama.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ อาราชิยามะ (เฮอันโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-arashiyama-1-7',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ อาราชิยามะ (เฮอันโบราณ)',
        'The Will-o''-the-Wisp Ghost Light of Arashiyama (เฮอันโบราณ)',
        'ghost',
        'เกียวโต (ญี่ปุ่น)',
        'Kyoto (Japan)',
        'อาราชิยามะ',
        'Arashiyama',
        34.9666,
        135.6322,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น เกียวโต (ญี่ปุ่น) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ อาราชิยามะ',
        'A chilling paranormal account from Kyoto (Japan). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Arashiyama.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เฮอันโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เฮอันโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ อาราชิยามะ',
        'Never whistle or look back if hearing whispers along twilight pathways in Arashiyama.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ อาราชิยามะ (เฮอันโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-arashiyama-1-7',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด อาราชิยามะ (เฮอันโบราณ)',
        'The Amphibious Troglodyte of Arashiyama (เฮอันโบราณ)',
        'monster',
        'เกียวโต (ญี่ปุ่น)',
        'Kyoto (Japan)',
        'อาราชิยามะ',
        'Arashiyama',
        34.9666,
        135.6322,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เกียวโต (ญี่ปุ่น) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ อาราชิยามะ',
        'Eyewitness reports of a formidable cryptid stalking Kyoto (Japan). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Arashiyama.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เฮอันโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เฮอันโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ อาราชิยามะ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Arashiyama.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด อาราชิยามะ (เฮอันโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

