        'A grim cautionary curse chronicle from Kyoto (Japan). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Arashiyama.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เฮอันโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
