        'pin-monster-mount-bromo-2-15',
        'ปีศาจจำแลงร่างล่อลวงคนเดินทาง ภูเขาไฟโบรโม (มัชปาหิต)',
        'The Deceptive Shapeshifting Stalker of Mount Bromo (มัชปาหิต)',
        'monster',
        'ชวาตะวันออก (อินโดนีเซีย)',
        'East Java (Indonesia)',
        'ภูเขาไฟโบรโม',
        'Mount Bromo',
        -7.9725,
        112.9531,
        'whisper',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ชวาตะวันออก (อินโดนีเซีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ภูเขาไฟโบรโม',
        'Eyewitness reports of a formidable cryptid stalking East Java (Indonesia). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Mount Bromo.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว มัชปาหิต ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native มัชปาหิต folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ภูเขาไฟโบรโม',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Mount Bromo.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"ปีศาจจำแลงร่างล่อลวงคนเดินทาง ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

