        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-baguio-2-16',
        'เสียงสะอื้นไห้ใต้สะพานหินโบราณ บากีโอ (คอร์ดิลเลรา)',
        'The Phantom Sobs Beneath Stone Bridge of Baguio (คอร์ดิลเลรา)',
        'ghost',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3872,
        120.6411,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น ลูซอน (ฟิลิปปินส์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ บากีโอ',
        'A chilling paranormal account from Luzon (Philippines). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Baguio.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว คอร์ดิลเลรา ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of คอร์ดิลเลรา oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ บากีโอ',
        'Never whistle or look back if hearing whispers along twilight pathways in Baguio.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงสะอื้นไห้ใต้สะพานหินโบราณ บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
